/*
 * A157751  Triangle of coefficients of polynomials F(n,x) in descending
 *          powers of x generated by F(n,x)=(x+1)*F(n-1,x)+F(n-1,-x), with
 *          initial F(0,x)=1.
 * https://oeis.org/A157751
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is the nth coefficient in the triangle of * coefficients of
 *            F(n,x) defined by generating function * F(n,x) =
 *            (x+1)F(n-1,x)+F(n-1,-x), F(0,x)=1. * * For row r=2m (even):
 *            value = C(m + floor(k/2), k) · 2^k * For row r=2m+1 (odd): value
 *            = C(m + ceil(k/2), k) · 2^k * where k is the position with...
 * Range:     u8 n <= 41, u16 n <= 114, u32 n <= 396, u64 n <= 1465,
 *            u128 n <= 5150, big any n
 * Helpers:   binom, pow2
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/binom.h"
#include "../utils/pow2.h"

seq_t a(idx_t n)
{
    /* Find the row r such that the cumulative number of terms up
     * to row r exceeds n.  The cumulative number up to row r is
     * (r+1)(r+2)/2.
     */
    idx_t r = 0;
    while ((unsigned __int128)(r + 1) * (r + 2) / 2 <= n) {
        ++r;
    }

    /* Cumulative terms up to the previous row (row r-1) */
    unsigned __int128 prev = (unsigned __int128)r * (r + 1) / 2;
    idx_t k = (idx_t)(n - prev);          /* position within row */

    /* Base index for the binomial parameter */
    idx_t m = r / 2;                       /* floor(r/2) */

    /* Compute the top parameter of the binomial coefficient */
    idx_t top;
    if ((r & 1ULL) == 0) {                 /* even row r = 2m */
        top = m + (k >> 1);                /* floor(k/2) */
    } else {                               /* odd row r = 2m+1 */
        top = m + ((k + 1) >> 1);          /* ceil(k/2) */
    }

    seq_t bin = binom(top, k);             /* binomial coefficient */
    seq_t two = pow2(k);                   /* 2^k */

    return bin * two;
}
